using AcademyDesk.Api.Data;using AcademyDesk.Api.Domain.Entities;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcademyDesk.Api.Controllers;
[ApiController][Route("api/academies/{academyId:guid}/academic-governance")]public sealed class AcademicGovernanceController(AcademyDeskDbContext db):ControllerBase{[HttpGet("grading-schemes")]public async Task<ActionResult> Schemes(Guid academyId,CancellationToken t)=>Ok(await db.GradingSchemes.AsNoTracking().Where(x=>x.AcademyId==academyId).ToListAsync(t));[HttpPost("grading-schemes")]public async Task<ActionResult> AddScheme(Guid academyId,GradingSchemeRequest r,CancellationToken t){if(string.IsNullOrWhiteSpace(r.Name)||r.PassingPercent<0||r.PassingPercent>100)return BadRequest();db.GradingSchemes.Add(new GradingScheme{AcademyId=academyId,Name=r.Name.Trim(),PassingPercent=r.PassingPercent,BandsJson=r.BandsJson??"[]"});await db.SaveChangesAsync(t);return Ok();}[HttpGet("prerequisites")]public async Task<ActionResult> Prerequisites(Guid academyId,CancellationToken t)=>Ok(await db.CoursePrerequisites.AsNoTracking().Where(x=>x.AcademyId==academyId).ToListAsync(t));[HttpPost("prerequisites")]public async Task<ActionResult> AddPrerequisite(Guid academyId,PrerequisiteRequest r,CancellationToken t){if(r.CourseId==r.RequiredCourseId||!await db.Courses.AnyAsync(x=>x.AcademyId==academyId&&x.Id==r.CourseId,t)||!await db.Courses.AnyAsync(x=>x.AcademyId==academyId&&x.Id==r.RequiredCourseId,t))return BadRequest();db.CoursePrerequisites.Add(new CoursePrerequisite{AcademyId=academyId,CourseId=r.CourseId,RequiredCourseId=r.RequiredCourseId});await db.SaveChangesAsync(t);return Ok();}}
public sealed record GradingSchemeRequest(string Name,decimal PassingPercent,string? BandsJson);public sealed record PrerequisiteRequest(Guid CourseId,Guid RequiredCourseId);
